function discoveryTerrain(local=false){return `<svg class="discovery-terrain" viewBox="0 0 1000 760" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="map-meadow" width="70" height="62" patternUnits="userSpaceOnUse"><path d="m12 37 3-7 3 7m30 13 2-5 3 5" fill="none" stroke="#8da96c" stroke-width="2" opacity=".45"/></pattern><pattern id="map-field" width="14" height="14" patternUnits="userSpaceOnUse" patternTransform="rotate(-23)"><path d="M0 0V14" stroke="#b5be78" stroke-width="6"/></pattern></defs><path fill="#ceddb1" d="M0 0H1000V760H0Z"/><path fill="#bdd399" d="M0 30Q190 120 280 10L580 0Q520 200 740 130L1000 180V510Q710 420 640 670L340 760Q420 530 170 570L0 620Z"/><path fill="url(#map-meadow)" d="M0 0H1000V760H0Z"/><path d="M-30 530Q140 390 230 470T500 470T760 400T1040 270" fill="none" stroke="#a9c6b5" stroke-width="58"/><path d="M-30 530Q140 390 230 470T500 470T760 400T1040 270" fill="none" stroke="#bbd8d0" stroke-width="42"/><path d="M240 -40Q160 150 380 260T610 450T390 800" fill="none" stroke="#b5b88b" stroke-width="28"/><path d="M240 -40Q160 150 380 260T610 450T390 800" fill="none" stroke="#ecdfb8" stroke-width="21"/><path d="M380 260Q750 180 1050 110M610 450Q800 600 1020 690" fill="none" stroke="#ecdfb8" stroke-width="14"/><path d="M0 160Q160 210 210 370M80 760Q140 570 330 590" fill="none" stroke="#e3d6af" stroke-width="12"/><path d="m640 30 270 25-12 100-250-12Z M90 580l180 34-38 120-190-25Z M730 540l200 70-50 110-220-60Z" fill="url(#map-field)" opacity=".7"/><path d="m0 20 130-20L80 120 0 140Z" fill="#9fbc87"/></svg>`}
function discoveryTrees(){return `<div class="discovery-trees" aria-hidden="true">${[[9,13],[14,21],[85,21],[90,29],[76,75],[82,80],[14,77],[66,7],[6,63],[92,56]].map(([x,y],i)=>`<img src="art/tree.svg" alt="" style="left:${x}%;top:${y}%;width:${i%2?6:8}%">`).join('')}</div>`}
neighborCities=function(){const cities=[farmLocations[2],farmLocations[1],farmLocations[0]];return heading('Карта ферм','Выберите город на карте.')+`<section class="discovery-map city-discovery" aria-label="Схематичная карта городов">${discoveryTerrain()}${discoveryTrees()}<span class="map-compass" aria-hidden="true">↑<small>С</small></span><span class="map-region region-north">СЕВЕРО-ЗАПАД</span><span class="map-region region-center">ЦЕНТР</span><span class="map-region region-south">ЮГ</span>${cities.map((c,i)=>`<a class="discovery-pin city-map-pin point-${i}" href="#farms-${c.id}"><span class="pin-village"><img src="art/imported/${['farm_house_lvl7','farm_house_lvl5','farm_lvl3'][i]}.svg" alt=""><img src="art/imported/farm_house_lvl2.svg" alt=""></span><span class="discovery-label"><strong>${c.name}</strong><small>3 демо-хозяйства · зайти →</small></span></a>`).join('')}<span class="map-key">Иллюстрация · расположение условное</span></section><div class="map-footnote">Демо-фермы доступны во всех городах. Реальная площадка подключена в Белореченске.</div>`};
neighborDirectory=function(city){const c=neighborCity(city);if(!c)return neighborCities();return `<a class="room-back" href="#farms">← Карта городов</a>`+heading(c.name,'Нажмите на нарисованную ферму, чтобы зайти в гости.')+`<section class="discovery-map local-discovery" aria-label="Карта демонстрационных хозяйств: ${c.name}">${discoveryTerrain(true)}${discoveryTrees()}<span class="map-compass" aria-hidden="true">↑<small>С</small></span><span class="map-region region-north">${c.name.toUpperCase()} · ОКРЕСТНОСТИ</span>${neighborFarms.filter(f=>f.city===city).map((f,i)=>`<a class="discovery-pin farm-map-pin farm-point-${i}" href="#visit-${f.id}" aria-label="Зайти в ${f.name}, демо-хозяйство"><span class="map-homestead"><img class="map-farm-house" src="art/imported/${f.house}.svg" alt=""><span class="map-farm-beds">${neighborBeds(f).slice(0,6).map(b=>`<i class="${b.covered?'mini-covered':''}"><span>${b.crop==='Огурцы'?'🥒':b.crop==='Томаты'?'🍅':'🌱'}</span></i>`).join('')}</span></span><span class="discovery-label"><strong>${f.avatar} ${f.name}</strong><small>Грядки: ${f.count} · теплицы: ${f.covers}</small><em>Демо · ${f.owner} · зайти →</em></span></a>`).join('')}<span class="map-key">Демо-мир · вымышленные хозяйства</span></section><div class="map-footnote">Схема для знакомства с сервисом. Это не адреса и не реальные пользователи.</div>`};
render();
